306	// Restore 从 Export 产生的 JSON 文本创建一个独立的钱包。
307	//
308	// 恢复不重新计时：所有截止时刻与会话到期时间沿用备份中的绝对时刻，
309	// 恢复前先按恢复时的当前时间处理全部到期请求（待审批过期、已预留超时
310	// 全额退回，释放时间仍为原截止时刻）。既有终态与历史记录不改写；过期或
311	// 吊销的会话、停用或结束的策略可以恢复，但不会重新获得授权。恢复后被
312	// 超时退回的余额可立即用于新申请，旧请求的迟到结算不能再扣走这笔钱。
313	//
314	// 空文本、非法 JSON、缺少必需数据、不支持的版本、编号重复、未知状态或
315	// 账本类型、非法金额或策略参数、悬空引用、申请会话不属于使用账户、
316	// 请求出资账户与策略不符，或余额/累计金额与请求求和不一致（含求和超出
317	// int64 范围），都返回包装了具体原因的 ErrBackupInvalid，绝不会返回
318	// 部分恢复的钱包。曾经批准成功并实际预留费用的超门槛请求（恢复时仍为
319	// 已预留，或后来已结算、已取消、已预留超时）还必须通过审批时限核对：
320	// 保存的等待截止时刻必须与提交时刻加策略等待时长、策略结束时间、申请
321	// 会话到期时间三者的最早值一致（缺失、提前、推迟都拒绝），且批准决定
322	// 必须发生在提交时刻及之后、等待截止时刻之前（恰在提交时刻批准可以
323	// 接受，恰到截止时刻批准必须拒绝）；该核对只针对备份记载的批准历史，
324	// 不以恢复时的当前时间替代批准时间，因此期限内已批准的请求即使恢复时
325	// 等待期限、申请会话或策略时间窗均已结束也照常恢复，不重新计时。
326	// 任一策略现存预留费用与已结算实际费用的合计严格超过其
327	// 共享累计上限时同样拒绝（同一策略的多个使用账户合并计算，不同策略分别
328	// 判断；待审批、已取消、被拒绝、已过期及预留超时的请求不占用额度），
329	// 该检查针对备份保存的资金占用状态、在恢复时的到期自动退回之前完成：
330	// 合计恰好等于上限合法，上限恰为 MaxInt64 时也不缩小可接受的金额范围。
331	// 任一账户的可用余额加上该账户在所有策略下仍处于已预留
332	// 状态的费用之和超出 int64 上限时同样拒绝（即使各请求、各策略金额分别
333	// 合法）：否则取消或预留超时的退回会使余额越界；校验在恢复时的到期
334	// 自动退回之前完成，预留尚未到期也当场拒绝。恢复出的钱包与原钱包、同一
335	// 备份恢复出的其他钱包互不影响。
336	func Restore(data []byte) (*Wallet, error) {
337		if len(bytes.TrimSpace(data)) == 0 {
338			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
339		}
340	
341		var b backupV1
342		dec := json.NewDecoder(bytes.NewReader(data))
343		if err := dec.Decode(&b); err != nil {
344			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
345		}
346		// 不允许备份对象之后还有多余的 JSON 值；忽略空白。
347		if _, err := dec.Token(); err != io.EOF {
348			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
349		}
350		if b.Version != backupVersion {
351			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
352		}
353	
354		w := New()
355		if err := w.restoreLocked(&b); err != nil {
356			return nil, err
357		}
358		return w, nil
359	}
360	
361	// restoreAt 仅供同包测试使用：与 Restore 相同，但显式指定恢复时刻，
362	// 便于确定性地验证恢复时的到期处理。
363	func restoreAt(data []byte, now time.Time) (*Wallet, error) {
364		if len(bytes.TrimSpace(data)) == 0 {
365			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
366		}
367		var b backupV1
368		dec := json.NewDecoder(bytes.NewReader(data))
369		if err := dec.Decode(&b); err != nil {
370			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
371		}
372		if _, err := dec.Token(); err != io.EOF {
373			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
374		}
375		if b.Version != backupVersion {
376			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
377		}
378		w := New()
379		w.now = func() time.Time { return now }
380		if err := w.restoreLocked(&b); err != nil {
381			return nil, err
382		}
383		return w, nil
384	}
385	
386	// restoreLocked 逐段构建并校验新钱包；任何失败都返回错误，调用方因此
387	// 绝不会拿到部分恢复的钱包。
388	func (w *Wallet) restoreLocked(b *backupV1) error {
389		// ---- 账户 ----
390		if b.Accounts == nil {
391			return fmt.Errorf("%w: missing accounts", ErrBackupInvalid)
392		}
393		accountIDs := make(map[string]struct{}, len(b.Accounts))
394		reservedByAccount := make(map[string]int64)
395		for i, a := range b.Accounts {
396			if a.ID == "" {
397				return fmt.Errorf("%w: account[%d] has empty id", ErrBackupInvalid, i)
398			}
399			if _, dup := accountIDs[a.ID]; dup {
400				return fmt.Errorf("%w: duplicate account id %q", ErrBackupInvalid, a.ID)
401			}
402			if a.Available < 0 {
403				return fmt.Errorf("%w: account %q available balance is negative: %d", ErrBackupInvalid, a.ID, a.Available)
404			}
405			if a.Reserved < 0 {
406				return fmt.Errorf("%w: account %q reserved balance is negative: %d", ErrBackupInvalid, a.ID, a.Reserved)
407			}
408			accountIDs[a.ID] = struct{}{}
409			w.accounts[a.ID] = &account{
410				id:        a.ID,
411				available: a.Available,
412				reserved:  a.Reserved,
413				createdAt: a.CreatedAt.std(),
414			}
415		}
416	
417		// ---- 会话 ----
418		if b.Sessions == nil {
419			return fmt.Errorf("%w: missing sessions", ErrBackupInvalid)
420		}
421		sessionByID := make(map[string]*session, len(b.Sessions))
422		for i, s := range b.Sessions {
423			if s.ID == "" {
424				return fmt.Errorf("%w: session[%d] has empty id", ErrBackupInvalid, i)
425			}
426			if _, dup := sessionByID[s.ID]; dup {
427				return fmt.Errorf("%w: duplicate session id %q", ErrBackupInvalid, s.ID)
428			}
429			if s.AccountID == "" || s.DeviceID == "" {
430				return fmt.Errorf("%w: session %q missing account or device id", ErrBackupInvalid, s.ID)
431			}
432			if _, ok := accountIDs[s.AccountID]; !ok {
433				return fmt.Errorf("%w: session %q references unknown account %q", ErrBackupInvalid, s.ID, s.AccountID)
434			}
435			sess := &session{
436				id:        s.ID,
437				accountID: s.AccountID,
438				deviceID:  s.DeviceID,
439				expiresAt: s.ExpiresAt.std(),
440				revoked:   s.Revoked,
441				createdAt: s.CreatedAt.std(),
442			}
443			sessionByID[s.ID] = sess
444			w.sessions[s.ID] = sess
445		}
446	
447		// ---- 策略 ----
448		if b.Policies == nil {
449			return fmt.Errorf("%w: missing policies", ErrBackupInvalid)
450		}
451		policyByID := make(map[string]*policy, len(b.Policies))
452		for i, p := range b.Policies {
453			if p.ID == "" {
454				return fmt.Errorf("%w: policy[%d] has empty id", ErrBackupInvalid, i)
455			}
456			if _, dup := policyByID[p.ID]; dup {
457				return fmt.Errorf("%w: duplicate policy id %q", ErrBackupInvalid, p.ID)
458			}
459			if err := validatePolicyParams(p); err != nil {
460				return fmt.Errorf("%w: policy %q: %v", ErrBackupInvalid, p.ID, err)
461			}
462			if _, ok := accountIDs[p.PayerAccountID]; !ok {
463				return fmt.Errorf("%w: policy %q references unknown payer account %q", ErrBackupInvalid, p.ID, p.PayerAccountID)
464			}
465			allowed := make(map[string]struct{}, len(p.AllowedAccountIDs))
466			for j, id := range p.AllowedAccountIDs {
467				if id == "" {
468					return fmt.Errorf("%w: policy %q allowed account[%d] is empty", ErrBackupInvalid, p.ID, j)
469				}
470				if _, ok := accountIDs[id]; !ok {
471					return fmt.Errorf("%w: policy %q references unknown allowed account %q", ErrBackupInvalid, p.ID, id)
472				}
473				if _, dup := allowed[id]; dup {
474					return fmt.Errorf("%w: policy %q lists allowed account %q more than once", ErrBackupInvalid, p.ID, id)
475				}
476				allowed[id] = struct{}{}
477			}
478			if p.ReservedTotal < 0 || p.SpentTotal < 0 {
479				return fmt.Errorf("%w: policy %q totals must not be negative (reserved %d spent %d)", ErrBackupInvalid, p.ID, p.ReservedTotal, p.SpentTotal)
480			}
481			po := &policy{
482				id:                   p.ID,
483				payerAccountID:       p.PayerAccountID,
484				allowedAccounts:      allowed,
485				operation:            p.Operation,
486				payee:                p.Payee,
487				startsAt:             p.StartsAt.std(),
488				endsAt:               p.EndsAt.std(),
489				maxPerRequest:        p.MaxPerRequest,
490				maxTotal:             p.MaxTotal,
491				approvalThreshold:    p.ApprovalThreshold,
492				approvalWait:         p.ApprovalWait.std(),
493				maxReserveDuration:   p.MaxReserveDuration.std(),
494				reservedTotal:        p.ReservedTotal,
495				spentTotal:           p.SpentTotal,
496				deactivated:          p.Deactivated,
497				deactivatedAt:        p.DeactivatedAt.std(),
498				deactivatorAccountID: p.DeactivatorAccountID,
499				deactivateReason:     p.DeactivateReason,
500			}
501			// 停用信息自洽：停用标志必须与停用时间/理由同时出现；停用账户必须
502			// 存在；未停用不得携带任何停用记录。
503			if po.deactivated {
504				if po.deactivatedAt.IsZero() || po.deactivateReason == "" {
505					return fmt.Errorf("%w: policy %q marked deactivated but missing deactivation time or reason", ErrBackupInvalid, p.ID)
506				}
507				if po.deactivatorAccountID != "" {
508					if _, ok := accountIDs[po.deactivatorAccountID]; !ok {
509						return fmt.Errorf("%w: policy %q deactivator references unknown account %q", ErrBackupInvalid, p.ID, po.deactivatorAccountID)
510					}
511				}
512			} else if !po.deactivatedAt.IsZero() || po.deactivatorAccountID != "" || po.deactivateReason != "" {
513				return fmt.Errorf("%w: policy %q not deactivated but carries deactivation info", ErrBackupInvalid, p.ID)
514			}
515			policyByID[p.ID] = po
516			w.policies[p.ID] = po
517		}
518	
519		// ---- 请求 ----
520		if b.Requests == nil {
521			return fmt.Errorf("%w: missing requests", ErrBackupInvalid)
522		}
523		reqKeys := make(map[requestKey]struct{}, len(b.Requests))
524		reservedSumByPolicy := make(map[string]int64)
525		spentSumByPolicy := make(map[string]int64)
526		for i, r := range b.Requests {
527			if err := validateRequestRef(r, i, accountIDs, sessionByID, policyByID); err != nil {
528				return err
529			}
530			key := requestKey{accountID: r.AccountID, requestID: r.RequestID}
531			if _, dup := reqKeys[key]; dup {
532				return fmt.Errorf("%w: duplicate request id %q under account %q", ErrBackupInvalid, r.RequestID, r.AccountID)
533			}
534			reqKeys[key] = struct{}{}
535	
536			state := RequestState(r.State)
537			if state < RequestReserved || state > RequestReservationExpired {
538				return fmt.Errorf("%w: request %q/%q has unknown state %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.State)
539			}
540			if r.EstimatedFee <= 0 {
541				return fmt.Errorf("%w: request %q/%q estimated fee must be positive: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.EstimatedFee)
542			}
543			if r.ActualFee < 0 {
544				return fmt.Errorf("%w: request %q/%q actual fee is negative: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.ActualFee)
545			}
546			if r.ReserveDuration.std() < 0 {
547				return fmt.Errorf("%w: request %q/%q reserve duration is negative", ErrBackupInvalid, r.AccountID, r.RequestID)
548			}
549	
550			req := &request{
551				policyID:          r.PolicyID,
552				requestID:         r.RequestID,
553				accountID:         r.AccountID,
554				payerAccountID:    r.PayerAccountID,
555				sessionID:         r.SessionID,
556				operation:         r.Operation,
557				payee:             r.Payee,
558				estimatedFee:      r.EstimatedFee,
559				actualFee:         r.ActualFee,
560				state:             state,
561				createdAt:         r.CreatedAt.std(),
562				settledAt:         r.SettledAt.std(),
563				waitDeadline:      r.WaitDeadline.std(),
564				reservedAt:        r.ReservedAt.std(),
565				reserveDuration:   r.ReserveDuration.std(),
566				reserveDeadline:   r.ReserveDeadline.std(),
567				reserveExpiredAt:  r.ReserveExpiredAt.std(),
568				decidedAt:         r.DecidedAt.std(),
569				approverAccountID: r.ApproverAccountID,
570				rejectReason:      r.RejectReason,
571			}
572			if err := validateRequestTimingAndState(req, policyByID[r.PolicyID], sessionByID[r.SessionID]); err != nil {
573				return fmt.Errorf("%w: request %q/%q: %v", ErrBackupInvalid, r.AccountID, r.RequestID, err)
574			}
575			w.requests[key] = req
576	
577			// 累加各账户/策略“按请求推算”的金额，稍后与快照余额核对。
578			// 只有当前仍处于已预留的请求才占用账户预留与策略预留总额。
579			if state == RequestReserved {
580				sum, ok := addInt64(reservedByAccount[req.payerAccountID], req.estimatedFee)
581				if !ok {
582					return fmt.Errorf("%w: account %q reserved sum overflows int64", ErrBackupInvalid, req.payerAccountID)
583				}
584				reservedByAccount[req.payerAccountID] = sum
585				sum, ok = addInt64(reservedSumByPolicy[req.policyID], req.estimatedFee)
586				if !ok {
587					return fmt.Errorf("%w: policy %q reserved sum overflows int64", ErrBackupInvalid, req.policyID)
588				}
589				reservedSumByPolicy[req.policyID] = sum
590			}
591			if state == RequestSettled {
592				sum, ok := addInt64(spentSumByPolicy[req.policyID], req.actualFee)
593				if !ok {
594					return fmt.Errorf("%w: policy %q spent sum overflows int64", ErrBackupInvalid, req.policyID)
595				}
596				spentSumByPolicy[req.policyID] = sum
597			}
598		}
599	
600		// ---- 账户预留余额 == 已预留请求预估费用之和 ----
601		for id, acc := range w.accounts {
602			if got, want := acc.reserved, reservedByAccount[id]; got != want {
603				return fmt.Errorf("%w: account %q reserved %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
604			}
605		}
606	
607		// ---- 可用余额 + 现存预留不得超过 int64 上限 ----
608		// 取消或预留超时会把预留全额退回可用余额：合计一旦超出 MaxInt64，
609		// 退回时余额就会越界变负。reservedByAccount 按出资账户汇总该账户在
610		// 所有策略下仍处于已预留状态的费用（待审批不冻结费用，已结算、已取消、
611		// 已预留超时的费用不再占用预留，故均不计入）。本检查必须在恢复时的
612		// 到期自动退回之前完成，使“恢复即超时退款”的备份也不能蒙混过关；
613		// 合计恰好等于上限合法（随后退回恰好得到上限金额）。
614		for id, acc := range w.accounts {
615			if _, ok := addInt64(acc.available, reservedByAccount[id]); !ok {
616				return fmt.Errorf("%w: account %q available %d plus reserved %d overflows int64", ErrBackupInvalid, id, acc.available, reservedByAccount[id])
617			}
618		}
619	
620		// ---- 策略预留总额/已花费总额 == 请求求和，且合计不得超过累计上限 ----
621		// 现存预留费用与已结算的实际费用共同占用策略的共享累计额度；同一策略的
622		// 多个使用账户合计判断，不同策略分别判断。待审批不冻结费用，已取消、被
623		// 拒绝、待审批过期、预留超时的请求均不计入，故上方求和本就不含它们。
624		// 严格超过累计上限的备份自相矛盾（正常流程在受理时就会拒绝），必须整体
625		// 拒绝；合计恰好等于上限合法。本检查针对备份保存的资金占用状态，位于
626		// 恢复时的到期自动退回之前：即使某笔已预留请求恢复时已到期、将全额
627		// 退回，也不能先退回再让原本超额的备份通过。两项金额各自为 int64、
628		// 合计越过 int64 上限时，addInt64 先捕获溢出，不能误判为额度充足。
629		for id, p := range policyByID {
630			if got, want := p.reservedTotal, reservedSumByPolicy[id]; got != want {
631				return fmt.Errorf("%w: policy %q reserved total %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
632			}
633			if got, want := p.spentTotal, spentSumByPolicy[id]; got != want {
634				return fmt.Errorf("%w: policy %q spent total %d != sum of settled requests %d", ErrBackupInvalid, id, got, want)
635			}
636			used, ok := addInt64(reservedSumByPolicy[id], spentSumByPolicy[id])
637			if !ok {
638				return fmt.Errorf("%w: policy %q reserved %d plus spent %d overflows int64 and exceeds cumulative total limit %d",
639					ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
640			}
641			if used > p.maxTotal {
642				return fmt.Errorf("%w: policy %q reserved %d plus spent %d exceeds cumulative total limit %d",
643					ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
644			}
645		}
646	
647		// ---- 账本 ----
648		if b.Ledger == nil {
649			return fmt.Errorf("%w: missing ledger", ErrBackupInvalid)
650		}
651		w.ledger = make([]LedgerEntry, 0, len(b.Ledger))
652		for i, e := range b.Ledger {
653			kind := LedgerKind(e.Kind)
654			if kind < LedgerReserve || kind > LedgerReservationExpiration {
655				return fmt.Errorf("%w: ledger[%d] has unknown kind %d", ErrBackupInvalid, i, e.Kind)
656			}
657			if e.Amount < 0 {
658				return fmt.Errorf("%w: ledger[%d] amount is negative: %d", ErrBackupInvalid, i, e.Amount)
659			}
660			// 账本是历史留痕：其账户/请求编号允许为空或指向不存在的实体。
661			// 未被受理申请（必填字段缺失、使用账户或会话不存在等）同样会留下
662			// 拒绝记录，这些记录必须原样保留，不能因为找不到对应账户或请求而
663			// 丢弃或拒绝恢复。资金一致性由账户余额与现存请求的求和核对保证，
664			// 不依赖账本文本。PolicyID 若给出则必须存在（仅策略停用记录使用）。
665			if e.PolicyID != "" {
666				if _, ok := policyByID[e.PolicyID]; !ok {
667					return fmt.Errorf("%w: ledger[%d] references unknown policy %q", ErrBackupInvalid, i, e.PolicyID)
668				}
669			}
670			w.ledger = append(w.ledger, LedgerEntry{
671				Kind:      kind,
672				AccountID: e.AccountID,
673				RequestID: e.RequestID,
674				PolicyID:  e.PolicyID,
675				Amount:    e.Amount,
676				Reason:    e.Reason,
677				At:        e.At.std(),
678			})
679		}
680	
681		// ---- 恢复时按当前时间结清到期请求（不重新计时，只推进惰性状态） ----
682		// 处理顺序与导出保持一致：先释放已到期预留，再把到期的待审批转为过期，
683		// 两类记录均按各自截止时刻排序后追加到账本末尾。
684		now := w.now()
685		w.expireReservationsLocked(now)
686		w.expirePendingApprovalsLocked(now)
687		return nil
688	}
689	
690	// validatePolicyParams 校验策略条件与限额参数，规则与 SavePolicy 一致。
691	func validatePolicyParams(p policyBackupV1) error {
692		if p.Operation == "" || p.Payee == "" {
693			return errors.New("operation and payee are required")
694		}
695		if p.MaxPerRequest <= 0 || p.MaxTotal <= 0 {
696			return errors.New("limits must be positive")
697		}
698		if p.ApprovalThreshold < 0 {
699			return errors.New("approval threshold must not be negative")
700		}
701		if p.ApprovalThreshold > 0 {
702			if p.ApprovalThreshold > p.MaxPerRequest {
703				return fmt.Errorf("approval threshold %d exceeds per-request limit %d", p.ApprovalThreshold, p.MaxPerRequest)
704			}
705			if p.ApprovalWait <= 0 {
706				return errors.New("approval wait must be positive when approval is enabled")
707			}
708		}
709		if p.ApprovalWait < 0 || p.MaxReserveDuration < 0 {
710			return errors.New("durations must not be negative")
711		}
712		if !p.StartsAt.std().Before(p.EndsAt.std()) {
713			return errors.New("starts-at must be before ends-at")
714		}
715		if p.PayerAccountID == "" || len(p.AllowedAccountIDs) == 0 {
716			return errors.New("payer account and at least one allowed account are required")
717		}
718		return nil
719	}
720	
721	// validateRequestRef 校验请求的外键引用：账户、会话、策略均须存在；申请
722	// 会话必须属于使用账户；出资账户必须与策略一致；申请账户必须被策略允许。
723	func validateRequestRef(r requestBackupV1, i int, accounts map[string]struct{}, sessions map[string]*session, policies map[string]*policy) error {
724		where := fmt.Sprintf("request[%d] %q/%q", i, r.AccountID, r.RequestID)
725		if r.RequestID == "" || r.AccountID == "" || r.PolicyID == "" || r.SessionID == "" {
726			return fmt.Errorf("%w: %s missing required id (account/request/policy/session)", ErrBackupInvalid, where)
727		}
728		if _, ok := accounts[r.AccountID]; !ok {
729			return fmt.Errorf("%w: %s references unknown usage account %q", ErrBackupInvalid, where, r.AccountID)
730		}
731		if _, ok := accounts[r.PayerAccountID]; !ok {
732			return fmt.Errorf("%w: %s references unknown payer account %q", ErrBackupInvalid, where, r.PayerAccountID)
733		}
734		sess, ok := sessions[r.SessionID]
735		if !ok {
736			return fmt.Errorf("%w: %s references unknown session %q", ErrBackupInvalid, where, r.SessionID)
737		}
738		// 申请会话必须属于使用账户。
739		if sess.accountID != r.AccountID {
740			return fmt.Errorf("%w: %s session %q belongs to account %q, not usage account %q", ErrBackupInvalid, where, r.SessionID, sess.accountID, r.AccountID)
741		}
742		p, ok := policies[r.PolicyID]
743		if !ok {
744			return fmt.Errorf("%w: %s references unknown policy %q", ErrBackupInvalid, where, r.PolicyID)
745		}
746		// 请求出资账户必须与策略出资账户一致。
747		if r.PayerAccountID != p.payerAccountID {
748			return fmt.Errorf("%w: %s payer account %q does not match policy %q payer %q", ErrBackupInvalid, where, r.PayerAccountID, r.PolicyID, p.payerAccountID)
749		}
750		if _, ok := p.allowedAccounts[r.AccountID]; !ok {
751			return fmt.Errorf("%w: %s usage account %q is not allowed by policy %q", ErrBackupInvalid, where, r.AccountID, r.PolicyID)
752		}
753		return nil
754	}
755	
756	// validateReserveTiming 校验预留计时三元组自洽：duration 必须非负；
757	// duration>0 时 reservedAt 必填且 reserveDeadline 必须等于
758	// reservedAt+duration；duration==0 时 reserveDeadline 必须为零。
759	// reservedAt 是否必填由各状态自行决定（待审批取消的请求两者都没有）。
760	func validateReserveTiming(r *request) error {
761		if r.reserveDuration < 0 {
762			return errors.New("reserve duration must not be negative")
763		}
764		if r.reserveDuration > 0 {
765			if r.reservedAt.IsZero() {
766				return errors.New("reserve duration set but reserved_at is missing")
767			}
768			want := r.reservedAt.Add(r.reserveDuration)
769			if !r.reserveDeadline.Equal(want) {
770				return fmt.Errorf("reserve deadline %v does not match reserved_at+duration %v", r.reserveDeadline, want)
771			}
772		} else if !r.reserveDeadline.IsZero() {
773			return errors.New("reserve deadline set while reserve duration is zero")
774		}
775		return nil
776	}
777	
778	// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
779	// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
780	// 备份。sess 为该请求的申请会话。
781	func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
782		if r.createdAt.IsZero() {
783			return errors.New("request missing created_at")
784		}
785		if r.operation == "" || r.payee == "" {
786			return errors.New("operation and payee are required")
787		}
788		if r.operation != p.operation || r.payee != p.payee {
789			return fmt.Errorf("operation/payee do not match policy %q", p.id)
790		}
791		if r.estimatedFee > p.maxPerRequest {
792			return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
793		}
794		if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
795			return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
796		}
797		if r.actualFee > r.estimatedFee {
798			return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
799		}
800	
801		// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
802		// 只能来自待审批流程；其余请求只能直接预留。
803		approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
804		reservedOrigin := !r.reservedAt.IsZero()
805	
806		switch r.state {
807		case RequestReserved, RequestSettled, RequestReservationExpired:
808			// 这三类一定发生过预留。
809			if err := validateReservedOrigin(r, p, sess, approvalRequired, reservedOrigin); err != nil {
810				return err
811			}
812		case RequestPendingApproval, RequestRejected, RequestExpired:
813			// 这三类一定从未预留，且必须来自开启审批的策略。
814			if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
815				return err
816			}
817		case RequestCancelled:
818			// 取消可能来自待审批（从未预留）或已预留。
819			if reservedOrigin {
820				if err := validateReservedOrigin(r, p, sess, approvalRequired, true); err != nil {
821					return err
822				}
823			} else {
824				if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
825					return err
826				}
827			}
828		default:
829			return fmt.Errorf("unknown state %d", r.state)
830		}
831	
832		switch r.state {
833		case RequestReserved:
834			// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
835			// 且不得已记录超时。
836			if err := validateReserveTiming(r); err != nil {
837				return err
838			}
839			if !r.reserveExpiredAt.IsZero() {
840				return errors.New("reserved request must not carry reserve-expired time")
841			}
842			if r.actualFee != 0 || !r.settledAt.IsZero() {
843				return errors.New("reserved request must not be settled")
844			}
845			if r.rejectReason != "" {
846				return errors.New("reserved request must not carry a reject reason")
847			}
848		case RequestSettled:
849			if r.settledAt.IsZero() {
850				return errors.New("settled request missing settled_at")
851			}
852			if !r.reserveExpiredAt.IsZero() {
853				return errors.New("settled request must not carry reserve-expired time")
854			}
855			if r.settledAt.Before(r.reservedAt) {
856				return errors.New("settled_at is before reserved_at")
857			}
858			if err := validateReserveTiming(r); err != nil {
859				return err
860			}
861			if r.rejectReason != "" {
862				return errors.New("settled request must not carry a reject reason")
863			}
864		case RequestCancelled:
865			if r.actualFee != 0 || !r.settledAt.IsZero() {
866				return errors.New("cancelled request must not be settled")
867			}
868			if !r.reserveExpiredAt.IsZero() {
869				return errors.New("cancelled request must not carry reserve-expired time")
870			}
871			if r.rejectReason != "" {
872				return errors.New("cancelled request must not carry a reject reason")
873			}
874			if reservedOrigin {
875				if err := validateReserveTiming(r); err != nil {
876					return err
877				}
878			} else {
879				// 待审批取消：决定时间必填。
880				if r.decidedAt.IsZero() {
881					return errors.New("cancelled-from-pending request missing decided_at")
882				}
883			}
884		case RequestPendingApproval:
885			// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
886			// min(提交+等待时长, 策略结束, 申请会话到期)。
887			if r.actualFee != 0 || !r.settledAt.IsZero() {
888				return errors.New("pending request must not be settled")
889			}
890			if r.waitDeadline.IsZero() {
891				return errors.New("pending request missing wait deadline")
892			}
893			if r.approverAccountID != "" {
894				return errors.New("pending request must not carry an approver")
895			}
896			if r.rejectReason != "" {
897				return errors.New("pending request must not carry a reject reason")
898			}
899			if !r.waitDeadline.Equal(expectedWaitDeadline(r, p, sess)) {
900				return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, expectedWaitDeadline(r, p, sess))
901			}
902		case RequestRejected:
903			if r.decidedAt.IsZero() || r.rejectReason == "" {
904				return errors.New("rejected request missing decided_at or reason")
905			}
906		case RequestExpired:
907			if r.decidedAt.IsZero() {
908				return errors.New("expired request missing decided_at")
909			}
910			if r.rejectReason != "" {
911				return errors.New("expired request must not carry a reject reason")
912			}
913			// 惰性/停用过期的决定时刻不可能早于等待截止时刻。
914			if r.decidedAt.Before(r.waitDeadline) {
915				return errors.New("expired request decided before its wait deadline")
916			}
917		case RequestReservationExpired:
918			if r.reserveDuration <= 0 {
919				return errors.New("reservation-expired request must have a positive reserve duration")
920			}
921			if err := validateReserveTiming(r); err != nil {
922				return err
923			}
924			if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
925				return errors.New("reserve-expired-at must equal reserve deadline")
926			}
927			if r.actualFee != 0 || !r.settledAt.IsZero() {
928				return errors.New("reservation-expired request must not be settled")
929			}
930			if r.rejectReason != "" {
931				return errors.New("reservation-expired request must not carry a reject reason")
932			}
933		}
934		return nil
935	}
936	
937	// expectedWaitDeadline 计算审批路径请求的等待截止时刻：提交时刻 + 策略
938	// 等待时长、策略结束时间、申请会话到期时间三者中的最早值。待审批与已批准
939	// 预留的请求保存的等待截止时刻都必须与该值一致。
940	func expectedWaitDeadline(r *request, p *policy, sess *session) time.Time {
941		want := r.createdAt.Add(p.approvalWait)
942		if p.endsAt.Before(want) {
943			want = p.endsAt
944		}
945		if sess.expiresAt.Before(want) {
946			want = sess.expiresAt
947		}
948		return want
949	}
950	
951	// validateApprovalTiming 校验“经批准后预留”的请求保存的等待期限与批准
952	// 时刻自洽，防止备份中的资金占用绕过正常审批等待期限：
953	//   - 等待截止时刻不得缺失，且必须等于提交时刻+等待时长、策略结束时间、
954	//     申请会话到期时间三者的最早值，提前或推迟都拒绝；
955	//   - 批准（决定/预留）时刻必须不早于提交时刻（恰在提交时刻批准可以接受），
956	//     且严格早于等待截止时刻：恰到截止时刻的批准在正常审批中不可能发生
957	//     （截止时刻及之后请求只能进入待审批过期终态）。
958	//
959	// 该校验只针对备份记载的批准历史，与恢复时的当前时间无关：期限内已批准的
960	// 请求在恢复时即使等待期限、申请会话或策略时间窗均已结束也照常恢复。
961	func validateApprovalTiming(r *request, p *policy, sess *session) error {
962		if r.waitDeadline.IsZero() {
963			return errors.New("approved request missing wait deadline")
964		}
965		want := expectedWaitDeadline(r, p, sess)
966		if !r.waitDeadline.Equal(want) {
967			return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
968		}
969		if r.decidedAt.Before(r.createdAt) {
970			return fmt.Errorf("approval decided_at %v is before created_at %v", r.decidedAt, r.createdAt)
971		}
972		if !r.decidedAt.Before(r.waitDeadline) {
973			return fmt.Errorf("approval decided_at %v is not strictly before wait deadline %v", r.decidedAt, r.waitDeadline)
974		}
975		return nil
976	}
977	
978	// validateReservedOrigin 校验“发生过预留”的请求：预留计时字段必须齐全、
979	// 预留时长快照必须与策略一致，且审批路径（批准人、决定时间、等待期限）与
980	// 费用/门槛相匹配。对所有发生过预留的状态（已预留、已结算、预留超时、
981	// 已预留后取消）统一适用：超门槛的必须经出资账户在等待期限内于预留时刻
982	// 批准，未超门槛的直接受理、不得携带批准人或决定时间。
983	func validateReservedOrigin(r *request, p *policy, sess *session, approvalRequired, reservedOrigin bool) error {
984		if !reservedOrigin {
985			return errors.New("request is in a reserved-origin state but missing reserved_at")
986		}
987		if r.reserveDuration != p.maxReserveDuration {
988			return fmt.Errorf("reserve duration %v does not match policy max reserve duration %v", r.reserveDuration, p.maxReserveDuration)
989		}
990		if approvalRequired {
991			if r.approverAccountID != r.payerAccountID {
992				return errors.New("above-threshold request was reserved without payer approval")
993			}
994			if !r.decidedAt.Equal(r.reservedAt) {
995				return errors.New("approved request decided_at must equal reserved_at")
996			}
997			// 等待截止时刻与批准时刻必须是正常审批流程能够产生的历史：即使该
998			// 预留后来已经结算、取消或超时退回，也不放宽这一要求。
999			if err := validateApprovalTiming(r, p, sess); err != nil {
1000				return err
1001			}
1002		} else {
1003			if r.approverAccountID != "" {
1004				return errors.New("below-threshold request must not carry an approver")
1005			}
1006			if !r.decidedAt.IsZero() {
1007				return errors.New("directly reserved request must not carry decided_at")
1008			}
1009		}
1010		return nil
1011	}
1012	
1013	// validatePendingOrigin 校验“从未预留”的待审批系请求：不得携带任何预留
1014	// 计时字段，且策略必须开启审批、费用必须严格超过门槛。
1015	func validatePendingOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
1016		if reservedOrigin {
1017			return errors.New("request is in a pending-origin state but carries reserved_at")
1018		}
1019		if !approvalRequired {
1020			return errors.New("request is in an approval state although policy approval is not enabled for its fee")
1021		}
1022		if !r.reserveDeadline.IsZero() || !r.reserveExpiredAt.IsZero() || r.reserveDuration != 0 {
1023			return errors.New("pending-origin request must not carry reserve timing")
1024		}
1025		return nil
1026	}
1027

