1	package wallet
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// timeoutPolicy 在 validPolicy 基础上开启预留超时：最长预留时长 d，
12	// 默认关闭大额审批（申请直接预留）。
13	func timeoutPolicy(c *clock, d time.Duration) PolicySpec {
14		p := validPolicy(c)
15		p.ID = "p-timeout"
16		p.MaxReserveDuration = d
17		return p
18	}
19	
20	// timeoutApply 构造一条 p-timeout 下的申请（默认费用 20）。
21	func timeoutApply() RequestInput {
22		in := baseApply()
23		in.PolicyID = "p-timeout"
24		return in
25	}
26	
27	// setupTimeout 构造开启预留超时的钱包：出资账户 payer（100），使用账户
28	// u1/u2 各自一分钟会话，策略 p-timeout（单次 30、累计 50、最长预留 d）。
29	func setupTimeout(t *testing.T, d time.Duration) (*Wallet, *clock) {
30		t.Helper()
31		w, c := newTestWallet()
32		mustAccount(t, w, "payer", 100)
33		mustAccount(t, w, "u1", 0)
34		mustAccount(t, w, "u2", 0)
35		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(time.Hour)); err != nil {
36			t.Fatal(err)
37		}
38		if _, err := w.CreateSession("s2", "u2", "dev2", c.t.Add(time.Hour)); err != nil {
39			t.Fatal(err)
40		}
41		if err := w.SavePolicy(timeoutPolicy(c, d)); err != nil {
42			t.Fatal(err)
43		}
44		return w, c
45	}
46	
47	func TestSaveReserveTimeoutPolicyValidation(t *testing.T) {
48		w, c := newTestWallet()
49		mustAccount(t, w, "payer", 100)
50		mustAccount(t, w, "u1", 0)
51		mustAccount(t, w, "u2", 0)
52	
53		// 正值：接受并可查询。
54		good := timeoutPolicy(c, 30*time.Second)
55		if err := w.SavePolicy(good); err != nil {
56			t.Fatal(err)
57		}
58		pv, err := w.Policy("p-timeout")
59		if err != nil {
60			t.Fatal(err)
61		}
62		if pv.MaxReserveDuration != 30*time.Second {
63			t.Fatalf("max reserve duration = %v, want 30s", pv.MaxReserveDuration)
64		}
65	
66		// 负值：策略无效且不创建策略。
67		neg := good
