528		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 20, Reserved: 0}) {
529			t.Fatalf("balance after timeout = %+v", bal)
530		}
531		pa, _ := w.Policy("pa")
532		if pa.ReservedTotal != 0 {
533			t.Fatalf("pa reserved total = %d, want 0", pa.ReservedTotal)
534		}
535		if _, err := w.Apply(r2); err != nil {
536			t.Fatalf("pb request should reuse refunded funds: %v", err)
537		}
538		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 0, Reserved: 20}) {
539			t.Fatalf("balance = %+v, want {0 20}", bal)
540		}
541	
542		// 迟到结算不能把已被新申请使用的费用扣走。
543		if _, err := w.Settle("u1", "ra", 20); !errors.Is(err, ErrReservationExpired) {
