			mutate: func(r *requestBackupV1, _ *policyBackupV1) {
				r.SettledAt = timeJSON(t0.Add(10 * time.Hour))
			},
		},
		{
			name:      "zero actual fee settled at deadline",
			restoreAt: t0.Add(30 * time.Minute),
			mutate: func(r *requestBackupV1, _ *policyBackupV1) {
