		data := buildApprovedTimingBackup(t, t0, RequestSettled, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
			r.SettledAt = timeJSON(deadline.Add(-time.Nanosecond))
		})
		w2, err := restoreAt(data, t0.Add(24*time.Hour))
		if err != nil {
