// 增加结算期限。
func TestRestoreSettledWithoutReserveTimeoutKeepsUnlimited(t *testing.T) {
	t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	data := buildDirectSettledBackup(t, t0, func(r *requestBackupV1, p *policyBackupV1) {
